import{WORLD,WIRES,RULES,GROUND,head,surgePhase,condition,socketRadius,socketVertices,grabRadius}from'./model.js';
export function connectorShape(kind,r=22){return socketVertices(kind,r).map(([x,y],i)=>`${i?'L':'M'}${x} ${y}`).join('')+'Z';}
export function cablePath(nodes){let path=`M${nodes[0].x},${nodes[0].y}`;for(let i=0;i<nodes.length-1;i++){const a=nodes[Math.max(0,i-1)],b=nodes[i],c=nodes[i+1],d=nodes[Math.min(nodes.length-1,i+2)];path+=`C${b.x+(c.x-a.x)/6},${b.y+(c.y-a.y)/6} ${c.x-(d.x-b.x)/6},${c.y-(d.y-b.y)/6} ${c.x},${c.y}`;}return path;}
export function sparkPath(from,to,t,seed=1){const dx=to.x-from.x,dy=to.y-from.y,len=Math.hypot(dx,dy)||1;let path=`M${from.x} ${from.y}`;for(let i=1;i<=8;i++){const q=i/8,noise=Math.sin(Math.PI*q)*7*Math.sin(i*13.7+seed+t*34);path+=`L${from.x+dx*q-dy/len*noise} ${from.y+dy*q+dx/len*noise}`;}return path;}
function spark(a,b,t,seed,strong=false){const d=sparkPath(a,b,t,seed);return `<path d="${d}" fill="none" stroke="${strong?'#dba6ff':'#74c6ff'}" stroke-width="${strong?13:8}" opacity=".5" filter="url(#bloom)"/><path d="${d}" fill="none" stroke="#eaffff" stroke-width="${strong?3:1.8}"/>`;}
function arrow(p,dir){const from={x:p.x+dir.x*46,y:p.y+dir.y*46},to={x:p.x+dir.x*85,y:p.y+dir.y*85};return `M${from.x} ${from.y}L${to.x} ${to.y}M${to.x-dir.x*13-dir.y*7} ${to.y-dir.y*13+dir.x*7}L${to.x} ${to.y}L${to.x-dir.x*13+dir.y*7} ${to.y-dir.y*13-dir.x*7}`;}
export function cabinetMarkup(){return `<svg id="cabinet" viewBox="0 0 ${WORLD.width} ${WORLD.height}" role="img" aria-label="Live electrical cables. Catch a moving connector and hold it in its matching socket.">
<defs><linearGradient id="steel" x2=".65" y2="1"><stop stop-color="#596c72"/><stop offset=".4" stop-color="#27383f"/><stop offset="1" stop-color="#101b24"/></linearGradient><linearGradient id="chrome" x2="0" y2="1"><stop stop-color="#bdccca"/><stop offset=".2" stop-color="#5b727b"/><stop offset=".6" stop-color="#162a34"/><stop offset="1" stop-color="#a8bac0"/></linearGradient><radialGradient id="interior"><stop stop-color="#213039"/><stop offset="1" stop-color="#090f17"/></radialGradient><pattern id="grid" width="34" height="34" patternUnits="userSpaceOnUse"><path d="M34 0H0V34" fill="none" stroke="#779cb1" stroke-opacity=".08"/></pattern><pattern id="stripes" width="24" height="24" patternUnits="userSpaceOnUse" patternTransform="rotate(40)"><rect width="24" height="24" fill="#172129"/><rect width="10" height="24" fill="#b59d68"/></pattern><filter id="bloom" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="4"/></filter><radialGradient id="corona"><stop stop-color="#abdfff" stop-opacity=".4"/><stop offset="1" stop-color="#72aaff" stop-opacity="0"/></radialGradient><clipPath id="inside"><rect x="77" y="99" width="1050" height="553" rx="5"/></clipPath></defs>
<rect x="26" y="36" width="1148" height="669" rx="22" fill="url(#steel)" stroke="#70868e" stroke-width="3"/><rect x="57" y="77" width="1086" height="599" rx="11" fill="url(#interior)" stroke="url(#chrome)" stroke-width="15"/><rect x="79" y="100" width="1048" height="551" fill="url(#grid)"/>
<g class="small" pointer-events="none"><text x="96" y="65">CONTAINMENT // EMERGENCY FEED CABINET</text><text x="1106" y="65" text-anchor="end">FOUR KEYED COUPLINGS · LIVE WORKING</text></g>
<g fill="#111c24" stroke="#91a5ac" stroke-width="2" pointer-events="none">${[61,1138].flatMap(x=>[90,370,663].map(y=>`<circle cx="${x}" cy="${y}" r="6"/><path d="M${x-3} ${y+3}l6-6"/>`)).join('')}</g>
<g id="anchor-hardware" pointer-events="none">${WIRES.map(d=>`<rect x="107" y="${d.anchor.y-28}" width="64" height="56" rx="8" fill="url(#chrome)" stroke="#a8b8bb"/><circle cx="${d.anchor.x}" cy="${d.anchor.y}" r="18" fill="#0c1822" stroke="${d.colour}" stroke-width="5"/><text x="198" y="${d.anchor.y-33}" class="label" fill="${d.colour}">${d.number} / ${d.name}</text>`).join('')}</g>
<g id="socket-hardware" pointer-events="none">${WIRES.map(d=>`<g id="socket-${d.id}"><rect x="889" y="${d.socket.y-63}" width="144" height="126" rx="14" fill="url(#steel)" stroke="#7d969e" stroke-width="3"/><circle cx="${d.socket.x}" cy="${d.socket.y}" r="57" fill="url(#chrome)"/><circle id="opening-${d.id}" cx="${d.socket.x}" cy="${d.socket.y}" r="50" fill="#050e18" stroke="${d.colour}" stroke-width="3"/><path id="mouth-${d.id}" d="${connectorShape(d.shape,32)}" transform="translate(${d.socket.x} ${d.socket.y})" fill="${d.colour}" fill-opacity=".13" stroke="${d.colour}" stroke-width="3" opacity=".9"/><circle id="progress-${d.id}" cx="${d.socket.x}" cy="${d.socket.y}" r="64" fill="none" stroke="${d.colour}" stroke-width="5" stroke-dasharray="0 403" transform="rotate(-90 ${d.socket.x} ${d.socket.y})"/><text x="875" y="${d.socket.y-35}" text-anchor="end" class="label" fill="${d.colour}">${d.number} / ${d.name}</text><circle id="power-${d.id}" cx="1062" cy="${d.socket.y-37}" r="8" fill="#3a4851"/><text x="1062" y="${d.socket.y+63}" text-anchor="middle" class="small">SECTION ${d.number}</text><g id="system-${d.id}"></g></g>`).join('')}</g>
<g pointer-events="none"><rect x="${GROUND.x}" y="${GROUND.y}" width="${GROUND.width}" height="${GROUND.height}" fill="url(#chrome)" stroke="#95a7a8"/><rect x="${GROUND.x+6}" y="${GROUND.y+4}" width="${GROUND.width-12}" height="9" fill="url(#stripes)"/><text x="${GROUND.x+GROUND.width/2}" y="${GROUND.y+41}" text-anchor="middle" class="small">GROUNDED CABINET LIP</text></g>
<g id="cables" pointer-events="none" clip-path="url(#inside)">${WIRES.map(d=>`<path id="shadow-${d.id}" fill="none" stroke="#02080e" stroke-width="25" stroke-linecap="round"/><path id="cable-${d.id}" fill="none" stroke="${d.colour}" stroke-width="17" stroke-linecap="round"/><path id="stripe-${d.id}" fill="none" stroke="#16232b" stroke-width="5" stroke-dasharray="16 13" stroke-linecap="round"/><path id="shine-${d.id}" fill="none" stroke="#e4eeee" stroke-width="2" opacity=".27"/>`).join('')}</g>
<g id="effects" pointer-events="none" clip-path="url(#inside)"></g>
<g id="heads">${WIRES.map(d=>`<g id="head-${d.id}" class="connector" role="button" aria-label="Grab ${d.name} numbered connector head and drag it to the matching socket"><circle id="grip-ring-${d.id}" r="33" fill="#ffffff" fill-opacity=".025" stroke="${d.colour}" stroke-width="3" stroke-dasharray="7 6" opacity="0"/><path d="M-34-10H-14V10H-34Z" fill="#1b2930" stroke="${d.colour}" stroke-width="6"/><path d="${connectorShape(d.shape,RULES.headRadius-2.5)}" fill="url(#chrome)" stroke="${d.colour}" stroke-width="5"/><path d="${connectorShape(d.shape,12)}" fill="#0c1822" stroke="#dce8e8" stroke-width="2"/><text x="0" y="5" text-anchor="middle" font-size="12" font-family="monospace" fill="#eaffff">${d.number}</text><text id="grab-label-${d.id}" x="0" y="49" text-anchor="middle" font-size="10" font-weight="700" font-family="monospace" fill="${d.colour}">GRAB HEAD</text><circle id="catch-area-${d.id}" r="${RULES.catchRadius*.78}" fill="transparent"/><circle id="lock-${d.id}" r="29" fill="none" stroke="#d7eda4" stroke-width="7" stroke-dasharray="26 7" opacity="0"/></g>`).join('')}</g>
<g id="retainers" pointer-events="none">${WIRES.map(d=>`<g id="jaws-${d.id}" transform="translate(${d.socket.x} ${d.socket.y})"><path id="jaw-left-${d.id}" d="M-6-22H3V-12H-2V12H3V22H-6Z" fill="url(#chrome)" stroke="#cce6de" stroke-width="2"/><path id="jaw-right-${d.id}" d="M6-22H-3V-12H2V12H-3V22H6Z" fill="url(#chrome)" stroke="#cce6de" stroke-width="2"/></g><text id="seated-label-${d.id}" x="${d.socket.x}" y="${d.socket.y+48}" text-anchor="middle" class="small" fill="${d.colour}"></text>`).join('')}</g>
<g id="grip-feedback" pointer-events="none"></g><g id="completion" pointer-events="none" opacity="0"><rect id="restoration-frame" x="79" y="100" width="1048" height="551" fill="none" stroke="#c3dda3" stroke-width="5"/><path d="M88 691H1115" stroke="#c3dda3" stroke-width="5"/><text x="600" y="730" text-anchor="middle" class="success-text">EMERGENCY POWER RESTORED</text></g>
</svg>`;}
export function createRenderer(container){container.innerHTML=cabinetMarkup();const svg=container.querySelector('svg'),node=id=>svg.querySelector('#'+id),set=(id,name,value)=>node(id).setAttribute(name,value);
 function render(s,visualTime=s.time,reduced=false){const t=reduced?0:visualTime,effects=[];
  for(const w of s.wires){const d=WIRES.find(d=>d.id===w.id),h=head(w),path=cablePath(w.nodes),phase=surgePhase(s,w),held=s.grip?.wireId===w.id;
   for(const prefix of ['shadow','cable','stripe','shine'])set(prefix+'-'+w.id,'d',path);
   set('cable-'+w.id,'stroke-opacity',w.connected?.64:1);set('shine-'+w.id,'opacity',.18+w.tension*.3);
   set('head-'+w.id,'transform',`translate(${h.x} ${h.y})`);node('head-'+w.id).classList.toggle('held',held);node('head-'+w.id).classList.toggle('secured',w.connected);set('grip-ring-'+w.id,'r',grabRadius(s));set('grip-ring-'+w.id,'opacity',w.connected?0:held?1:phase.warning?.85:.58);set('grip-ring-'+w.id,'stroke',phase.warning?'#fff1b7':d.colour);set('grab-label-'+w.id,'opacity',w.connected||held?0:1);
   set('mouth-'+w.id,'d',connectorShape(d.shape,s.config.socketTolerance));
   const retained=w.state==='SEATED'||w.connected,unstable=s.cycle.phase==='WARNING'&&s.cycle.wireId===w.id,jitter=unstable&&!reduced?Math.sin(s.time*34)*1.8:0;
   set('catch-area-'+w.id,'r',grabRadius(s));set('jaws-'+w.id,'transform',`translate(${d.socket.x+jitter} ${d.socket.y})`);
   set('jaw-left-'+w.id,'transform',`translate(${retained?-21:-41} 0)`);set('jaw-right-'+w.id,'transform',`translate(${retained?21:41} 0)`);
   node('seated-label-'+w.id).textContent=unstable?'CONTACT UNSTABLE':w.connected?'LOCKED · ONLINE':w.state==='SEATED'?`HOLD ${Math.ceil((1-w.progress)*s.config.engagementTime*10)/10}s` :'';
   if(w.state==='SEATED'&&s.time-w.seatedAt<.3){const age=(s.time-w.seatedAt)/.3;effects.push(`<circle cx="${h.x}" cy="${h.y}" r="${48-age*20}" fill="none" stroke="${d.colour}" stroke-width="6" opacity="${1-age}"/>`);}
   set('opening-'+w.id,'r',socketRadius(s));set('progress-'+w.id,'stroke-dasharray',`${(w.progress*402.13).toFixed(2)} 403`);set('power-'+w.id,'fill',unstable?'#e7ae6f':w.connected?'#c8ed9a':'#354651');set('lock-'+w.id,'opacity',w.connected?1:0);set('lock-'+w.id,'stroke',unstable?'#ffb584':'#d7eda4');set('lock-'+w.id,'stroke-dasharray',unstable?'14 15':'26 7');
   if(unstable){effects.push(`<circle cx="${h.x}" cy="${h.y}" r="38" fill="none" stroke="#ffbd86" stroke-width="3" stroke-dasharray="7 5"/>`);if(reduced||Math.sin(s.time*17)>.35)effects.push(spark(h,{x:h.x-42,y:h.y-18},t,Number(d.number),true));}
   if(!w.connected){
    if(s.time-(w.lastFailureAt??-10)<.25)effects.push(spark(h,d.socket,t,Number(d.number)+13,true));
    effects.push(`<circle cx="${h.x}" cy="${h.y}" r="${phase.active?64:35}" fill="url(#corona)"/>`);
    const reach=phase.active?68:phase.warning?25+phase.charge*18:25;effects.push(spark({x:h.x+8,y:h.y-8},{x:h.x+Math.cos(t*2+Number(d.number))*reach,y:h.y-Math.sin(t*1.5+Number(d.number))*(reach*.7)-12},t,Number(d.number),phase.active));
    if(phase.warning){effects.push(`<circle cx="${h.x}" cy="${h.y}" r="${38+phase.charge*5}" fill="none" stroke="${d.colour}" stroke-width="${2+phase.charge*3*phase.magnitude}" stroke-dasharray="6 9" opacity="${.25+phase.charge*.6}"/>`);effects.push(spark({x:h.x-9,y:h.y+10},{x:h.x-14-phase.charge*20,y:h.y+24},t,Number(d.number)+7));}
    if(phase.warning||phase.active)effects.push(`<path d="${arrow(h,phase.direction)}" fill="none" stroke="${phase.active?'#daacff':'#ffe0a4'}" stroke-width="4" opacity="${phase.active?1:.4+.6*phase.charge}"/>`);
    if(s.time-w.lastReject<.2||s.time-w.lastGround<.2)effects.push(spark(h,w.lastEventPoint,t,12,true));
   }else if(s.time-w.lockedAt<.6){const age=(s.time-w.lockedAt)/.6;effects.push(`<circle cx="${h.x}" cy="${h.y}" r="${30+age*44}" fill="none" stroke="#dbf5b7" stroke-width="5" opacity="${1-age}"/>`);}
   if(d.id==='fan')node('system-'+d.id).innerHTML=`<g transform="translate(1062 ${d.socket.y+6}) rotate(${w.connected?s.time*210:0})" fill="${w.connected?'#b5d798':'#425761'}"><circle r="6"/>${[0,120,240].map(a=>`<path d="M0-5C15-35 36-12 12 5Z" transform="rotate(${a})"/>`).join('')}</g>`;
   if(d.id==='seal')node('system-'+d.id).innerHTML=`<rect x="1045" y="${d.socket.y-11}" width="34" height="50" rx="5" fill="#273b45" stroke="#7896a0"/><path d="M1062 ${d.socket.y-8}v${w.connected?39:12}" stroke="${w.connected?'#c8e8a7':'#718992'}" stroke-width="10"/>`;
   if(d.id==='vent')node('system-'+d.id).innerHTML=`<g transform="translate(1062 ${d.socket.y+9})" stroke="${w.connected?'#c8e8a7':'#718992'}" stroke-width="5">${[-13,0,13].map(y=>`<path d="M-21 ${y}h42" transform="rotate(${w.connected?-25:0} 0 ${y})"/>`).join('')}</g>`;
   if(d.id==='supply')node('system-'+d.id).innerHTML=`<rect x="1041" y="${d.socket.y-19}" width="43" height="58" rx="4" fill="#1f3039" stroke="#7896a0"/>${[0,1,2].map(i=>`<rect x="1048" y="${d.socket.y-11+i*15}" width="29" height="8" fill="${w.connected?'#bfdc9e':'#3d525d'}"/>`).join('')}`;
  }
  if(s.lastMissPoint&&s.time-s.lastMiss<.35)effects.push(`<circle cx="${s.lastMissPoint.x}" cy="${s.lastMissPoint.y}" r="8" fill="none" stroke="#e9b489" stroke-width="2"/>`);
  node('effects').innerHTML=effects.join('');
  if(s.grip){const w=s.wires.find(w=>w.id===s.grip.wireId),h=head(w),q=s.grip.desired;node('grip-feedback').innerHTML=`<path d="M${q.x} ${q.y}L${h.x} ${h.y}" stroke="#d9e6e6" stroke-width="1.5" stroke-dasharray="6 7" opacity=".6"/><circle cx="${q.x}" cy="${q.y}" r="11" fill="none" stroke="#f2f8e2" stroke-width="2"/><path d="M${q.x-17} ${q.y}h10m14 0h10m-17-17v10m0 14v10" stroke="#f2f8e2" stroke-width="2"/>`;}else node('grip-feedback').innerHTML='';
  set('restoration-frame','stroke-width',s.complete&&!reduced?4+8*Math.max(0,1-(s.time-s.completedAt)/.6):4);set('completion','opacity',s.complete&&s.cycle.phase!=='WARNING'?1:0);svg.dataset.complete=String(s.complete);return condition(s);
 }
 return {svg,render};
}
